402	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first.
403	func (s *Store) Invites(orgID string) []Invite {
404		s.mu.Lock()
405		defer s.mu.Unlock()
406		out := []Invite{}
407		for _, inv := range s.invites {
408			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
409				out = append(out, inv)
410			}
411		}
412		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
413		return out
414	}
415	
416	// RevokeInvite withdraws an invite.
417	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
418		s.mu.Lock()
419		defer s.mu.Unlock()
420		inv, ok := s.invites[id]
421		if !ok || inv.OrgID != orgID {
422			return Invite{}, ErrNotFound
423		}
424		if inv.RevokedAt == nil {
425			t := now.UTC()
426			inv.RevokedAt = &t
427			s.invites[id] = inv
428		}
429		return inv, nil
430	}
431	
432	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
433	// makes them a member with the invite's role and gives them a first API key.
434	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
435		s.mu.Lock()
436		defer s.mu.Unlock()
437		var inv Invite
438		found := false
439		for _, i := range s.invites {
440			if i.Token == token && token != "" {
441				inv, found = i, true
442				break
443			}
444		}
445		if !found || inv.RevokedAt != nil {
446			return User{}, Member{}, APIKey{}, ErrNotFound
447		}
448		var u User
449		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
450			u = s.users[id]
451		} else {
452			name = strings.TrimSpace(name)
453			if name == "" {
454				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
455			}
456			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
457			s.users[u.ID] = u
458			s.usersByEmail[normEmail(u.Email)] = u.ID
459		}
460		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
461		if err != nil {
462			return User{}, Member{}, APIKey{}, err
463		}
464		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
465		if err != nil {
466			return User{}, Member{}, APIKey{}, err
467		}
468		t := now.UTC()
469		inv.AcceptedAt = &t
470		s.invites[inv.ID] = inv
471		return u, m, k, nil
472	}
