51	// Plan returns one of an organization's plans.
52	func (s *Store) Plan(orgID, id string) (Plan, bool) {
53		s.mu.Lock()
54		defer s.mu.Unlock()
55		p, ok := s.plans[id]
56		if !ok || p.OrgID != orgID {
57			return Plan{}, false
58		}
59		return p, true
60	}
