178	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
179	// canceled, the longest overdue first.
180	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		out := []Subscription{}
184		for _, sub := range s.subs {
185			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
186				out = append(out, copySub(sub))
187			}
188		}
189		sort.Slice(out, func(i, j int) bool {
190			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
191				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
192			}
193			return out[i].ID < out[j].ID
194		})
195		return out
196	}
