77	func (s *Store) FindCustomerByEmail(orgID, email string) (Customer, bool) {
78		s.mu.Lock()
79		defer s.mu.Unlock()
80		id, ok := s.customersByEmail[normEmail(email)]
81		if !ok {
82			return Customer{}, false
83		}
84		return copyCustomer(s.customers[id]), true
85	}
86	
87	// UpdateCustomer changes a customer with f, which may refuse with an error. The ID and organization cannot change.
88	func (s *Store) UpdateCustomer(orgID, id string, f func(*Customer) error) (Customer, error) {
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		old, ok := s.customers[id]
92		if !ok || old.OrgID != orgID {
93			return Customer{}, ErrNotFound
94		}
95		c := copyCustomer(old)
96		if err := f(&c); err != nil {
97			return Customer{}, err
98		}
99		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
100		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
101		if c.Name == "" || !validEmail(c.Email) {
102			return Customer{}, invalid("a customer needs a name and a valid email address")
103		}
104		if c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_") {
105			return Customer{}, invalid("a payment method looks like pm_...")
106		}
107		if newKey := normEmail(c.Email); newKey != normEmail(old.Email) {
108			if other, ok := s.customersByEmail[newKey]; ok && s.customers[other].OrgID == orgID {
109				return Customer{}, ErrEmailTaken
110			}
111			delete(s.customersByEmail, normEmail(old.Email))
112			s.customersByEmail[newKey] = c.ID
113		}
114		s.customers[id] = c
115		return copyCustomer(c), nil
116	}
117	
118	// DeleteCustomer removes a customer.
119	func (s *Store) DeleteCustomer(orgID, id string) error {
120		s.mu.Lock()
121		defer s.mu.Unlock()
122		c, ok := s.customers[id]
123		if !ok || c.OrgID != orgID {
124			return ErrNotFound
125		}
126		delete(s.customers, id)
127		if s.customersByEmail[normEmail(c.Email)] == id {
128			delete(s.customersByEmail, normEmail(c.Email))
129		}
130		return nil
131	}
132	
133	func copyCustomer(c Customer) Customer {
134		if c.Metadata != nil {
135			m := make(map[string]string, len(c.Metadata))
136			for k, v := range c.Metadata {
137				m[k] = v
138			}
139			c.Metadata = m
140		}
141		return c
142	}
143	
144	func sortCustomers(cs []Customer) {
145		sort.Slice(cs, func(i, j int) bool {
146			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
147				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
148			}
149			return cs[i].ID < cs[j].ID
150		})
151	}
