83	func parsePage(w http.ResponseWriter, r *http.Request) (page, bool) {
84		p := page{limit: 20}
85		if v := r.URL.Query().Get("limit"); v != "" {
86			n, err := strconv.Atoi(v)
87			if err != nil || n < 1 || n > 100 {
88				writeError(w, http.StatusBadRequest, "invalid_limit", "limit is a whole number from 1 to 100")
89				return page{}, false
90			}
91			p.limit = n
92		}
93		if v := r.URL.Query().Get("cursor"); v != "" {
94			b, err := base64.RawURLEncoding.DecodeString(v)
95			var c cursor
96			if err != nil || json.Unmarshal(b, &c) != nil || c.ID == "" {
97				writeError(w, http.StatusBadRequest, "invalid_cursor", "the cursor is not one this API gave out")
98				return page{}, false
99			}
100			p.after = &c
101		}
102		return p, true
103	}
