58	// or with ?status=. The store finds the page, so the cost does not grow with the organization's other invoices.
59	func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, p auth.Principal) {
60		pg, ok := parsePage(w, r)
61		if !ok {
62			return
63		}
64		q := r.URL.Query()
65		status := store.InvoiceStatus(q.Get("status"))
66		if status != "" && status != store.InvoiceOpen && status != store.InvoicePaid && status != store.InvoiceVoid {
67			writeError(w, http.StatusBadRequest, "invalid_status", "status is open, paid or void")
68			return
69		}
70		var after *store.InvoiceCursor
71		if pg.after != nil {
72			after = &store.InvoiceCursor{Created: pg.after.T, ID: pg.after.ID}
73		}
74		invs, more := s.store.InvoicePage(p.OrgID, store.InvoiceFilter{CustomerID: q.Get("customer_id"), SubscriptionID: q.Get("subscription_id"), Status: status}, after, pg.limit)
75		items := make([]invoiceView, 0, len(invs))
76		next := ""
77		for _, inv := range invs {
